// Tema 8 · fase 2 de las marcas (20/10/2026): apartados con marca suya sin pregunta oficial (cobertura-marcas.js 8).
// EXOF / ✱ / R → banco oficial (8-240…); solo EX → banco IA (8-ia-51…). Cita literal comprobada contra tema8/lopj.txt.
// Uso: node prompts/herramientas/tema8/preguntas-marcas-t8.js [--check]
const N = ['Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial', 'LOPJ', 'Del Poder Judicial'];
const R = [];
let k = 0;
// q(artículo, rúbrica, enunciado, correcta, [3 incorrectas], cita literal, ia?, explicación?) — la correcta rota de posición (A/B/C/D)
const q = (a, r, e, ok, mal, t, ia, p) => { const pos = (k++ * 3 + (ia ? 1 : 0)) % 4; const o = mal.slice(); o.splice(pos, 0, ok); R.push({ n: N, ia: !!ia, a, r, e, o, c: pos, t, p }); };

q('art. 2.1', 'Jurisdicción y potestad jurisdiccional', 'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente:',
  'A los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.',
  ['A los jueces y magistrados integrantes del Poder Judicial y, supletoriamente, al Ministerio Fiscal en los casos previstos en la ley.', 'A los Tribunales y a los órganos del Consejo General del Poder Judicial determinados en las leyes orgánicas.', 'A los jueces y juezas de carrera, sin que puedan ejercerla los Tribunales consuetudinarios y tradicionales reconocidos en la ley.'],
  '1. El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.');
q('art. 7.2', 'Derechos fundamentales', 'En especial, los derechos enunciados en el artículo 53.2 de la Constitución se reconocerán, en todo caso, de conformidad con su contenido constitucionalmente declarado, sin que las resoluciones judiciales puedan:',
  'Restringir, menoscabar o inaplicar dicho contenido.', ['Interpretarlo conforme a la jurisprudencia del Tribunal Supremo ni modificarlo mediante recurso de casación.', 'Aplicarlo de forma directa ni suspender su ejercicio mediante medidas cautelares provisionales.', 'Ampliar su alcance más allá de lo previsto por el legislador orgánico en cada caso concreto.'],
  '2. En especial, los derechos enunciados en el artículo 53.2 de la Constitución se reconocerán, en todo caso, de conformidad con su contenido constitucionalmente declarado, sin que las resoluciones judiciales puedan restringir, menoscabar o inaplicar dicho contenido.');
q('art. 16.2', 'Publicidad y Tribunales de Honor', 'Se prohíben:', 'Los Tribunales de Honor en la Administración de Justicia.',
  ['Los Tribunales de Excepción y los Tribunales consuetudinarios y tradicionales en la Administración de Justicia.', 'Los Tribunales de Honor y los Tribunales militares en tiempo de paz dentro del territorio nacional.', 'Los Tribunales especiales en la Administración de Justicia, salvo el Tribunal del Jurado.'],
  '2. Se prohíben los Tribunales de Honor en la Administración de Justicia.');
q('art. 18.3', 'Ejecución de resoluciones', 'Lo dispuesto en el artículo sobre el cumplimiento de las resoluciones judiciales se entiende sin perjuicio del derecho de gracia, cuyo ejercicio, de acuerdo con la Constitución y las leyes, corresponde:',
  'Al Rey.', ['Al Presidente del Gobierno.', 'Al Consejo de Ministros, a propuesta del Ministro de Justicia.', 'Al Tribunal Supremo, previo informe del Ministerio Fiscal.'],
  '3. Lo dispuesto en este artículo se entiende sin perjuicio del derecho de gracia, cuyo ejercicio, de acuerdo con la Constitución y las leyes, corresponde al Rey.');
q('art. 19.1', 'Participación en la Administración de Justicia', 'Los ciudadanos de nacionalidad española podrán ejercer la acción popular:',
  'En los casos y formas establecidos en la ley.', ['En todos los procesos penales, sin necesidad de que lo prevea una ley expresa.', 'En los casos y formas que establezca el Consejo General del Poder Judicial mediante acuerdo.', 'Únicamente en los procesos penales por delitos contra la Corona y forma de Gobierno.'],
  '1. Los ciudadanos de nacionalidad española podrán ejercer la acción popular, en los casos y formas establecidos en la ley.');
q('art. 19.2', 'Participación en la Administración de Justicia', 'Asimismo, podrán participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales:',
  'Que la Ley determine.', ['Cuya pena máxima sea superior a cinco años de prisión.', 'Que determine el Consejo General del Poder Judicial.', 'Que se sigan ante la Audiencia Provincial de cada capital.'],
  '2. Asimismo, podrán participar en la Administración de Justicia: mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la Ley determine; en los Tribunales consuetudinarios y tradicionales y en los demás casos previstos en esta Ley.');
q('art. 19.3', 'Participación en la Administración de Justicia', 'Tiene el carácter de Tribunal consuetudinario y tradicional:',
  'El Tribunal de las Aguas de la Vega Valenciana.', ['El Consejo de Hombres Buenos de la Vega Valenciana.', 'El Tribunal de las Aguas de Murcia.', 'El Tribunal de Aguas de la Huerta de Orihuela, junto con el Consejo de Hombres Buenos.'],
  '3. Tiene el carácter de Tribunal consuetudinario y tradicional el Tribunal de las Aguas de la Vega Valenciana.');
q('art. 19.4', 'Participación en la Administración de Justicia', 'Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado:',
  'Consejo de Hombres Buenos de Murcia.', ['Tribunal de las Aguas de Murcia.', 'Consejo de Hombres Buenos de Valencia.', 'Tribunal de las Aguas de la Huerta de Murcia.'],
  '4. Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado Consejo de Hombres Buenos de Murcia.');
q('art. 21.1', 'Extensión y límites de la jurisdicción', 'Los Tribunales civiles españoles conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido en:',
  'Los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas.', ['Las leyes españolas y, supletoriamente, en los tratados y convenios internacionales en los que España sea parte.', 'Los tratados internacionales ratificados por España y en los reglamentos de la Unión Europea únicamente.', 'Las normas de la Unión Europea y en las leyes orgánicas, con exclusión de los convenios internacionales.'],
  '1. Los Tribunales civiles españoles conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido en los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas.');
q('art. 22', 'Competencia judicial internacional', 'Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:',
  'Derechos reales y arrendamientos de bienes inmuebles que se hallen en España, entre otras.', ['Contratos de trabajo celebrados en territorio español, entre otras.', 'Relaciones personales y patrimoniales entre cónyuges residentes en España, entre otras.', 'Delitos cometidos por españoles fuera del territorio nacional, entre otras.'],
  'Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:');
q('art. 22 bis.1', 'Sumisión', 'En aquellas materias en que una norma expresamente lo permita, los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio, se hayan sometido:',
  'Expresa o tácitamente a ellos.', ['Expresamente a ellos y por escrito ante notario.', 'Tácitamente a ellos mediante la sola presentación de la demanda.', 'Expresamente a ellos, siempre que alguna tenga su domicilio en España.'],
  '1. En aquellas materias en que una norma expresamente lo permita, los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio, se hayan sometido expresa o tácitamente a ellos.');
q('art. 22 bis.2', 'Sumisión', 'Se entenderá por acuerdo de sumisión expresa aquel pacto por el cual las partes deciden atribuir a los Tribunales españoles el conocimiento de ciertas o todas las controversias que hayan surgido o puedan surgir entre ellas respecto de una determinada relación jurídica, contractual o no contractual. La competencia establecida por sumisión expresa:',
  'Se extenderá a la propia validez del acuerdo de sumisión.', ['No alcanzará a la validez del acuerdo de sumisión, que se juzgará por el Derecho extranjero.', 'Se limitará a las controversias ya surgidas, sin alcanzar a las futuras.', 'Excluirá la competencia de los órganos judiciales exclusivamente competentes conforme al artículo 22.'],
  '2. Se entenderá por acuerdo de sumisión expresa aquel pacto por el cual las partes deciden atribuir a los Tribunales españoles el conocimiento de ciertas o todas las controversias que hayan surgido o puedan surgir entre ellas respecto de una determinada relación jurídica, contractual o no contractual. La competencia establecida por sumisión expresa se extenderá a la propia validez del acuerdo de sumisión.', true);
q('art. 22 quáter.c)', 'Competencia en defecto de otros criterios', 'En defecto de los criterios anteriores, los Tribunales españoles serán competentes en materia de relaciones personales y patrimoniales entre cónyuges, nulidad matrimonial, separación y divorcio, siempre que ningún otro Tribunal extranjero tenga competencia, entre otros supuestos:',
  'Cuando ambos cónyuges posean residencia habitual en España al tiempo de la interposición de la demanda.', ['Cuando uno solo de los cónyuges haya nacido en España, aunque ambos residan en el extranjero.', 'Cuando el matrimonio se hubiera celebrado ante autoridad española, aunque ninguno resida en España.', 'Cuando el demandante lleve al menos tres meses de residencia habitual en España.'],
  'c) En materia de relaciones personales y patrimoniales entre cónyuges, nulidad matrimonial, separación y divorcio y sus modificaciones, siempre que ningún otro Tribunal extranjero tenga competencia, cuando ambos cónyuges posean residencia habitual en España al tiempo de la interposición de la demanda');
q('art. 23.1', 'Jurisdicción española en el orden penal', 'En el orden penal corresponderá a la jurisdicción española el conocimiento de las causas por delitos y faltas cometidos en territorio español o cometidos a bordo de buques o aeronaves españoles, sin perjuicio de lo previsto:',
  'En los tratados internacionales en los que España sea parte.', ['En las normas de la Unión Europea sobre cooperación judicial penal únicamente.', 'En las leyes orgánicas que regulan la jurisdicción militar.', 'En los convenios bilaterales de extradición suscritos por el Gobierno.'],
  '1. En el orden penal corresponderá a la jurisdicción española el conocimiento de las causas por delitos y faltas cometidos en territorio español o cometidos a bordo de buques o aeronaves españoles, sin perjuicio de lo previsto en los tratados internacionales en los que España sea parte.');
q('art. 23.2', 'Jurisdicción española en el orden penal', 'También conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren:',
  'Españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho.', ['Españoles o extranjeros que residan habitualmente en España, aunque no hayan adquirido la nacionalidad.', 'Españoles, con exclusión de los extranjeros que hubieran adquirido después la nacionalidad española.', 'Extranjeros que hubieran adquirido la nacionalidad española antes de la comisión del hecho.'],
  '2. También conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho y concurrieren los siguientes requisitos:', true);
q('art. 23.2.a)', 'Jurisdicción española en el orden penal', 'Para que la jurisdicción española conozca de delitos cometidos fuera del territorio nacional por españoles, se exige que el hecho sea punible en el lugar de ejecución, salvo que:',
  'En virtud de un Tratado internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito.', ['El delito se hubiera cometido contra un español, en cuyo caso el requisito no es exigible.', 'El Ministerio Fiscal interponga querella ante los tribunales españoles en cualquier caso.', 'El agraviado haya obtenido en el extranjero una resolución favorable firme.'],
  'a) Que el hecho sea punible en el lugar de ejecución, salvo que, en virtud de un Tratado internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito, sin perjuicio de lo dispuesto en los apartados siguientes.');
q('art. 23.4.e)', 'Jurisdicción universal', 'La jurisdicción española conocerá de los hechos cometidos por españoles o extranjeros fuera del territorio nacional susceptibles de tipificarse, según la ley española, como delitos de:',
  'Terrorismo, siempre que concurra alguno de los supuestos previstos en la ley.', ['Terrorismo, siempre que el procedimiento se dirija exclusivamente contra un español.', 'Terrorismo, sin necesidad de que concurra ninguno de los supuestos previstos en la ley.', 'Terrorismo cometido únicamente contra víctimas de nacionalidad española.'],
  'e) Terrorismo, siempre que concurra alguno de los siguientes supuestos:');
q('art. 23.4.j)', 'Jurisdicción universal', 'Entre los delitos cometidos fuera del territorio nacional de que conoce la jurisdicción española, se encuentran los de constitución, financiación o integración en grupo u organización criminal, siempre que se trate de grupos que actúen con miras a la comisión en España de un delito castigado con una pena máxima:',
  'Igual o superior a tres años de prisión.', ['Superior a cinco años de prisión.', 'Igual o superior a dos años de prisión.', 'Igual o superior a cuatro años de prisión.'],
  'j) Delitos de constitución, financiación o integración en grupo u organización criminal o delitos cometidos en el seno de los mismos, siempre que se trate de grupos u organizaciones que actúen con miras a la comisión en España de un delito que esté castigado con una pena máxima igual o superior a tres años de prisión.', true);
q('art. 23.4.k)', 'Jurisdicción universal', 'La jurisdicción española conocerá de los delitos contra la libertad e indemnidad sexual:',
  'Cometidos sobre víctimas menores de edad, siempre que concurran los supuestos previstos en la ley.', ['Cometidos sobre cualquier víctima, siempre que el autor sea de nacionalidad española.', 'Cometidos sobre víctimas menores de dieciséis años, sin otros requisitos.', 'Cometidos en el extranjero, siempre que el agraviado interponga querella en el plazo de un año.'],
  'k) Delitos contra la libertad e indemnidad sexual cometidos sobre víctimas menores de edad, siempre que:');
q('art. 25 (encabezamiento)', 'Competencia en el orden social', 'En el orden social, los jueces y juezas, así como los Tribunales españoles serán competentes:',
  'En las materias que enumera el propio artículo, como los derechos y obligaciones derivados de contrato de trabajo.', ['Únicamente en materia de Seguridad Social frente a entidades españolas.', 'En todo caso, con preferencia de cualquier otro, para cualquier pretensión de carácter laboral.', 'Solo cuando el contrato de trabajo se haya celebrado en territorio español.'],
  'En el orden social, los jueces y juezas, así como los Tribunales españoles serán competentes:');
q('art. 25.2.º', 'Competencia en el orden social', 'En el orden social, los Tribunales españoles serán competentes en materia de control de legalidad de los convenios colectivos de trabajo celebrados en España y de:',
  'Pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español.', ['Pretensiones derivadas de conflictos individuales de trabajo promovidos en territorio español.', 'Pretensiones de Seguridad Social frente a entidades españolas.', 'Conflictos colectivos de trabajo promovidos en cualquier Estado de la Unión Europea.'],
  '2.º En materia de control de legalidad de los convenios colectivos de trabajo celebrados en España y de pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español.');
q('art. 25.3.º', 'Competencia en el orden social', 'En el orden social, los Tribunales españoles serán competentes en materia de pretensiones de Seguridad Social frente a:',
  'Entidades españolas o que tengan domicilio, agencia, delegación o cualquier otra representación en España.', ['Entidades extranjeras con sede en la Unión Europea, aunque no tengan representación en España.', 'Cualquier entidad gestora, con independencia de su domicilio o de su representación en España.', 'Entidades españolas, con exclusión de las que tengan solo una agencia o delegación en España.'],
  '3.º En materia de pretensiones de Seguridad Social frente a entidades españolas o que tengan domicilio, agencia, delegación o cualquier otra representación en España.');
q('art. 26', 'Tribunales', 'Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes:',
  'Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo.', ['Jueces y juezas de paz, Juzgados de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Audiencia Nacional, Tribunal Supremo y Tribunal Constitucional.', 'Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo, sin Jueces de paz.', 'Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Audiencias Territoriales, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo.'],
  'Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes: a) Jueces y juezas de paz. b) Tribunales de Instancia. c) Audiencias Provinciales. d) Tribunales Superiores de Justicia. e) Tribunal Central de Instancia. f) Audiencia Nacional. g) Tribunal Supremo.');
q('art. 30', 'Organización territorial', 'El Estado se organiza territorialmente, a efectos judiciales, en:',
  'Municipios, Partidos, Provincias y Comunidades Autónomas.', ['Municipios, Comarcas, Provincias y Comunidades Autónomas.', 'Partidos, Provincias, Comunidades Autónomas y circunscripciones nacionales.', 'Municipios, Partidos judiciales, Distritos y Comunidades Autónomas.'],
  'El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas.');
q('art. 32.2', 'Partidos judiciales', 'La modificación de partidos se realizará, en su caso, en función:',
  'Del número de asuntos, de las características de la población, medios de comunicación y comarcas naturales.', ['Del número de asuntos y de la población, con independencia de los medios de comunicación existentes.', 'De las características de la población y de la extensión del territorio provincial únicamente.', 'Del número de asuntos, de las comarcas naturales y de las cargas de trabajo de los Juzgados.'],
  '2. La modificación de partidos se realizará, en su caso, en función del número de asuntos, de las características de la población, medios de comunicación y comarcas naturales.');
q('art. 35.1', 'Demarcación judicial', 'La demarcación judicial, que determinará la circunscripción territorial de los órganos judiciales, se establecerá:',
  'Por ley o, en los casos expresamente contemplados en esta norma, por real decreto.', ['Por real decreto o, en los casos expresamente contemplados en esta norma, por ley.', 'Por ley orgánica en todo caso, a propuesta del Consejo General del Poder Judicial.', 'Por acuerdo del Consejo General del Poder Judicial, previo informe del Gobierno.'],
  '1. La demarcación judicial, que determinará la circunscripción territorial de los órganos judiciales, se establecerá por ley o, en los casos expresamente contemplados en esta norma, por real decreto.');
q('art. 55 (encabezamiento)', 'Tribunal Supremo', 'El Tribunal Supremo estará integrado por las siguientes Salas:',
  'Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar.', ['Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Mercantil.', 'Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Social; Cuarta, de lo Contencioso-Administrativo; y Quinta, de lo Militar.', 'Primera, de lo Penal; Segunda, de lo Civil; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar.'],
  'El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar');
q('art. 55 bis', 'Tribunal Supremo', 'Las Salas de lo Civil y de lo Penal del Tribunal Supremo conocerán de la tramitación y enjuiciamiento de las acciones civiles y penales, respectivamente, dirigidas contra:',
  'La Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte.', ['El Rey o la Reina en ejercicio, su consorte y el Príncipe o Princesa de Asturias.', 'La Reina consorte, el consorte de la Reina y los miembros de la Familia Real, con exclusión del Heredero.', 'El Rey o Reina que hubiere abdicado, con exclusión de su consorte, y el Príncipe o Princesa de Asturias.'],
  'dichas Salas conocerán de la tramitación y enjuiciamiento de las acciones civiles y penales, respectivamente, dirigidas contra la Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte.');
q('art. 60.1', 'Tribunal Supremo', 'Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales:',
  'Del propio orden jurisdiccional que no tengan otro superior común.', ['De cualquier orden jurisdiccional que no tengan otro superior jerárquico.', 'Del propio orden jurisdiccional, cuando así lo decida la Sala de Gobierno.', 'De distinto orden jurisdiccional que no tengan otro superior común.'],
  '1. Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común.');
q('art. 63.1', 'Audiencia Nacional', 'La Audiencia Nacional se compondrá de:',
  'Su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones.', ['Su Presidente, los Presidentes de Sala y un número fijo de doce magistrados por cada Sala.', 'Su Presidente, un Vicepresidente y los magistrados que determine el Consejo General del Poder Judicial.', 'Los Presidentes de Sala y los magistrados que determine la ley, sin Presidente propio.'],
  '1. La Audiencia Nacional se compondrá de su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones.');
q('art. 64.1', 'Audiencia Nacional', 'La Audiencia Nacional estará integrada por las siguientes Salas:',
  'De Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social.', ['De Apelación, de lo Civil, de lo Penal y de lo Contencioso-Administrativo.', 'De lo Penal, de lo Contencioso-Administrativo, de lo Social y de lo Militar.', 'De Apelación, de lo Penal, de lo Social y de lo Mercantil.'],
  '1. La Audiencia Nacional estará integrada por las siguientes Salas: De Apelación. De lo Penal. De lo Contencioso-Administrativo. De lo Social.', true);
q('art. 65.1.º', 'Sala de lo Penal de la Audiencia Nacional', 'La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos, entre otros:',
  'Defraudaciones y maquinaciones para alterar el precio de las cosas que produzcan grave repercusión en la economía nacional.', ['Homicidios dolosos cometidos por funcionarios públicos en el ejercicio de su cargo.', 'Delitos contra la propiedad intelectual cometidos en el territorio de una sola Audiencia.', 'Delitos de lesiones graves cometidos fuera del territorio nacional por extranjeros.'],
  'c) Defraudaciones y maquinaciones para alterar el precio de las cosas que produzcan o puedan producir grave repercusión en la seguridad del tráfico mercantil, en la economía nacional o perjuicio patrimonial en una generalidad de personas en el territorio de más de una Audiencia.');
q('art. 65.1.º.a)', 'Sala de lo Penal de la Audiencia Nacional', 'La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento de los delitos:',
  'Contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno.', ['Contra los miembros de las Cortes Generales y del Gobierno en el ejercicio de sus cargos.', 'Contra el titular de la Corona y su Consorte, con exclusión del Sucesor o Sucesora.', 'Contra altos organismos de la Nación y la forma de Estado, con exclusión de la Corona.'],
  'a) Delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno.');
q('art. 65.4.º', 'Sala de lo Penal de la Audiencia Nacional', 'La Sala de lo Penal de la Audiencia Nacional conocerá de los recursos respecto a los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, y de la resolución de los procedimientos judiciales de extradición pasiva:',
  'Sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento.', ['Siempre que la detención hubiera tenido lugar en la provincia de Madrid.', 'Únicamente cuando el afectado resida en territorio nacional al tiempo de la detención.', 'Salvo que la detención se hubiese producido en el territorio de otra Audiencia Provincial.'],
  '4.º De los recursos respecto a los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, y la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento.');
q('art. 71', 'Tribunal Superior de Justicia', 'El Tribunal Superior de Justicia tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción:',
  'Al ámbito territorial de ésta.', ['Al ámbito de la provincia en que tenga su sede.', 'Al ámbito de la Comunidad Autónoma y de las ciudades con Estatuto de Autonomía limítrofes.', 'Al ámbito territorial de ésta, salvo en el orden contencioso-administrativo.'],
  'El Tribunal Superior de Justicia tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción al ámbito territorial de ésta.');
q('art. 72.1', 'Tribunal Superior de Justicia', 'El Tribunal Superior de Justicia estará integrado por las siguientes Salas:',
  'De lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social.', ['De lo Civil, de lo Penal y de lo Contencioso-Administrativo.', 'De lo Civil y Penal, de lo Contencioso-Administrativo, de lo Social y de Apelación.', 'De lo Civil y Penal, de lo Contencioso-Administrativo y de lo Mercantil.'],
  '1. El Tribunal Superior de Justicia estará integrado por las siguientes Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social.');
q('art. 73.3', 'Sala de lo Civil y Penal del TSJ', 'Como Sala de lo Penal, corresponde a la Sala de lo Civil y Penal del Tribunal Superior de Justicia, entre otras funciones:',
  'El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia.', ['El conocimiento de los recursos de casación contra las sentencias dictadas por las Audiencias Provinciales.', 'La instrucción y el fallo de las causas penales contra miembros del Gobierno de la Nación.', 'La decisión de las cuestiones de competencia entre órganos de distintas Comunidades Autónomas.'],
  '3. Como Sala de lo Penal, corresponde a esta Sala: a) El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia.');
q('art. 73.3.c)', 'Sala de lo Civil y Penal del TSJ', 'Como Sala de lo Penal, corresponde a la Sala de lo Civil y Penal del Tribunal Superior de Justicia el conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por:',
  'Las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes.', ['Las Secciones de Instrucción de los Tribunales de Instancia, así como el de todos los de queja.', 'La Audiencia Nacional, así como el de todos aquellos previstos por las leyes.', 'Los Juzgados de Paz, así como el de los recursos de casación que prevea la ley.'],
  'c) El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes.');
q('art. 73.6', 'Sala de lo Civil y Penal del TSJ', 'En el caso de que el número de asuntos lo aconseje, podrán crearse una o más Secciones e incluso Sala de lo Penal con su propia circunscripción territorial:',
  'En aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer los recursos de apelación.', ['En cualquier capital de provincia de la Comunidad Autónoma, para conocer de todos los asuntos penales.', 'En aquellas capitales que no sean sedes de otras Salas del Tribunal Superior, para conocer los recursos de casación.', 'En las ciudades con Estatuto de Autonomía, a los solos efectos de instruir las causas contra aforados.'],
  '6. En el caso de que el número de asuntos lo aconseje, podrán crearse una o más Secciones e incluso Sala de lo Penal con su propia circunscripción territorial en aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer los recursos de apelación');
q('art. 74.1.f)', 'Sala de lo Contencioso-Administrativo del TSJ', 'Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con:',
  'Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos.', ['Los actos y disposiciones de la Junta Electoral Central en materia de proclamación de electos.', 'Los acuerdos de las Juntas Electorales de Zona sobre elección de Alcaldes en municipios de menos de mil habitantes.', 'Los actos de las Cortes Generales y de las Asambleas Legislativas en materia de personal.'],
  'f) Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos y elección y proclamación de Presidentes y Presidentas de Corporaciones locales en los términos de la legislación electoral.');
q('art. 74.1.h)', 'Sala de lo Contencioso-Administrativo del TSJ', 'Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con:',
  'La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, reguladora del derecho de reunión.', ['La prohibición de manifestaciones convocadas en lugares de tránsito público, previstas en la Ley Orgánica 4/2015.', 'La disolución de reuniones previstas en la Ley Orgánica 9/1983, por orden de la autoridad gubernativa.', 'Los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito de la comunidad autónoma.'],
  'h) La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión.');
q('art. 74.1.i)', 'Sala de lo Contencioso-Administrativo del TSJ', 'Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán de los actos y resoluciones dictados por órganos de la Administración General del Estado cuya competencia se extienda a todo el territorio nacional y cuyo nivel orgánico sea:',
  'Inferior a Ministro, Ministra, Secretario o Secretaria de Estado, en materias de personal, propiedades especiales y expropiación forzosa.', ['Superior al de Director General, en materias de personal, propiedades especiales y sanciones.', 'Inferior a Subsecretario, en materias de personal, contratación y expropiación forzosa.', 'Igual al de Ministro o Secretario de Estado, en materias de personal y propiedades especiales.'],
  'i) Los actos y resoluciones dictados por órganos de la Administración General del Estado cuya competencia se extienda a todo el territorio nacional y cuyo nivel orgánico sea inferior a Ministro, Ministra, Secretario o Secretaria de Estado, en materias de personal, propiedades especiales y expropiación forzosa');
q('art. 82.1', 'Audiencias Provinciales', 'Las Audiencias Provinciales conocerán en el orden penal:',
  'De las causas por delitos que la ley determine, de los recursos que establezca la ley contra resoluciones de los Tribunales de Instancia y de las cuestiones de competencia, entre otras funciones.', ['Exclusivamente de las causas por delitos graves, quedando los recursos reservados a los Tribunales Superiores de Justicia.', 'De los recursos de casación contra las sentencias de las Secciones de Instrucción y de las cuestiones de competencia entre Comunidades.', 'Solo de las causas que la ley atribuya a la Sección de lo Penal, sin conocer de recursos.'],
  '1. Las Audiencias Provinciales conocerán en el orden penal:', true);
q('art. 82 bis.4', 'Audiencias Provinciales', 'Los acuerdos de reparto de asuntos de las Audiencias Provinciales serán objeto de publicación en el «Boletín Oficial del Estado» y producirán efectos:',
  'Desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.', ['Desde el día siguiente al de su publicación, salvo que se establezca otro momento posterior.', 'A los veinte días de su publicación, salvo que, por razones de urgencia, se establezca otro momento anterior.', 'Desde el inicio del semestre siguiente a aquel en que se adopten, sin excepción alguna.'],
  '4. Los acuerdos a que se refiere el presente artículo serán objeto de publicación en el "Boletín Oficial del Estado" y producirán efectos desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.', true);
q('art. 84.3', 'Tribunales de Instancia', 'Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran, entre otras, las siguientes circunstancias:',
  'Que en el Tribunal de Instancia hubiere dos o más Secciones.', ['Que en el Tribunal de Instancia hubiere tres o más Secciones.', 'Que en la Sección de que se trate existan cinco o más plazas judiciales.', 'Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a veinte.'],
  '3. Cada Tribunal de Instancia contará con una Presidencia. Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran las siguientes circunstancias: a) Que en el Tribunal de Instancia hubiere dos o más Secciones.', true);
q('art. 85', 'Tribunales de Instancia', 'Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a:',
  'Un partido judicial.', ['Una provincia.', 'Dos o más partidos judiciales de la misma provincia.', 'Una Comunidad Autónoma.'],
  'Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a un partido judicial.');
q('art. 86.4', 'Secciones de Familia, Infancia y Capacidad', 'En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe asumirá el conocimiento de los asuntos de familia:',
  'Cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad.', ['Cuando la Sala de Gobierno así lo acuerde de forma motivada.', 'Aunque se hubiere creado una Sección de Familia, Infancia y Capacidad en el partido.', 'Cuando el Consejo General del Poder Judicial no haya creado una Sección de Violencia sobre la Mujer.'],
  '4. En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe será quien asuma el conocimiento de los asuntos de familia cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad.');
q('art. 86.5', 'Secciones de Familia, Infancia y Capacidad', 'Las Secciones de Familia, Infancia y Capacidad conocerán de cuantas cuestiones se susciten en materia de familia en los términos previstos en las leyes. En todo caso, su jurisdicción será exclusiva y excluyente en las siguientes materias:',
  'Las relativas al matrimonio y a su régimen económico matrimonial, entre otras previstas en la ley.', ['Las relativas a la sucesión hereditaria y a las donaciones entre parientes, entre otras previstas en la ley.', 'Las relativas a los arrendamientos de vivienda habitual y a las ejecuciones hipotecarias.', 'Las relativas a la responsabilidad penal de los menores, entre otras previstas en la ley.'],
  'a) Las relativas al matrimonio y a su régimen económico matrimonial y las que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho.');
q('art. 89.7', 'Secciones de Violencia sobre la Mujer', 'Las Secciones de Violencia sobre la Mujer tendrán de forma exclusiva y excluyente competencia en el orden civil cuando concurran:',
  'Simultáneamente los requisitos que establece la ley.', ['Alguno de los requisitos que establece la ley, de forma alternativa.', 'Los requisitos que fije cada Sala de Gobierno para su territorio.', 'Simultáneamente los requisitos que establezca el Consejo General del Poder Judicial.'],
  '7. Las Secciones de Violencia sobre la Mujer tendrán de forma exclusiva y excluyente competencia en el orden civil cuando concurran simultáneamente los siguientes requisitos:', true);
q('art. 89 bis.7', 'Secciones de Violencia contra la Infancia y la Adolescencia', 'Si los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia corresponderá en todo caso:',
  'A la última.', ['A la primera.', 'A la que primero hubiera iniciado las diligencias.', 'A la que determine la Sala de Gobierno del Tribunal Superior.'],
  '7. En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia le corresponderá en todo caso a la última.', true);
q('art. 95', 'Tribunal Central de Instancia', 'En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará, entre otras, con las siguientes Secciones:',
  'Instrucción, Menores, Vigilancia Penitenciaria y de lo Contencioso-Administrativo.', ['Instrucción, Familia, Vigilancia Penitenciaria y de lo Social.', 'Instrucción, Menores, Violencia sobre la Mujer y de lo Mercantil.', 'Instrucción, Apelación, Vigilancia Penitenciaria y de lo Civil.'],
  'En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará con las siguientes Secciones: a) Sección de Instrucción', true);
q('art. 99', 'Jueces de paz', 'En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá:',
  'Un juez o una jueza de paz.', ['Un Juzgado de Primera Instancia e Instrucción.', 'Una Sección del Tribunal de Instancia del partido.', 'Un juez o una jueza de paz y un Secretario judicial.'],
  'En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz.');
q('art. 100.1', 'Juzgados de Paz', 'Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también:',
  'Las demás funciones que la ley les atribuya.', ['Las funciones de instrucción de las causas por faltas que determine el Gobierno.', 'Las funciones que les delegue la Audiencia Provincial.', 'Las demás funciones que les atribuya el Consejo General del Poder Judicial.'],
  '1. Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya.');
q('art. 378.2', 'Inamovilidad', 'Los jueces y magistrados que hayan sido nombrados por plazo determinado gozarán de inamovilidad:',
  'Sólo por ese tiempo.', ['Hasta la jubilación forzosa.', 'Por un período máximo de cinco años, prorrogable una vez.', 'Durante todo el tiempo que dure su carrera judicial.'],
  '2. Los que hayan sido nombrados por plazo determinado gozarán de inamovilidad sólo por ese tiempo.');
q('art. 379.1', 'Pérdida de la condición de juez', 'La condición de Jueces o Magistrados se perderá, entre otras causas:',
  'Por pérdida de la nacionalidad española o en virtud de sanción disciplinaria de separación de la Carrera Judicial.', ['Por traslado forzoso a otra plaza o por sanción disciplinaria de suspensión de funciones.', 'Por cumplir sesenta y cinco años de edad o por incapacidad temporal prolongada.', 'Por condena a pena privativa de libertad por razón de delito imprudente.'],
  'b) Por pérdida de la nacionalidad española. c) En virtud de sanción disciplinaria de separación de la Carrera Judicial.', true);
q('art. 383', 'Suspensión de jueces y magistrados', 'La suspensión de los Jueces y Magistrados sólo tendrá lugar, entre otros casos:',
  'Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.', ['Cuando por cualquier delito imprudente se hubiere dictado contra ellos auto de procesamiento.', 'Cuando se hubiere incoado contra ellos un expediente informativo por el Consejo General del Poder Judicial.', 'Cuando se hubiere dictado auto de prisión por cualquier delito, doloso o imprudente.'],
  '2.º Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.', true);
q('art. 385', 'Jubilación', 'Los Jueces y Magistrados sólo podrán ser jubilados:',
  'Por edad o por incapacidad permanente para el ejercicio de sus funciones.', ['Por edad o por incapacidad temporal prolongada para el ejercicio de sus funciones.', 'Por edad, por incapacidad permanente o por decisión del Consejo General del Poder Judicial.', 'Por incapacidad permanente para el ejercicio de sus funciones o por sanción disciplinaria.'],
  'Los Jueces y Magistrados sólo podrán ser jubilados: 1.º Por edad. 2.º Por incapacidad permanente para el ejercicio de sus funciones.');
q('art. 386.2', 'Jubilación', 'Los jueces y magistrados también podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo General del Poder Judicial con:',
  'Seis meses de antelación.', ['Tres meses de antelación.', 'Un año de antelación.', 'Un mes de antelación.'],
  '2. También podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo y General del Poder Judicial con seis meses de antelación');
q('art. 389 (encabezamiento)', 'Incompatibilidades', 'El cargo de Juez o Magistrado es incompatible:',
  'Con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial, entre otros supuestos.', ['Con el ejercicio de la docencia en materias jurídicas, entre otros supuestos.', 'Con la participación en actividades de producción literaria, científica o técnica, entre otros supuestos.', 'Con la administración del patrimonio personal o familiar, entre otros supuestos.'],
  'El cargo de Juez o Magistrado es incompatible: 1.º Con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial.');
q('art. 389.7.º', 'Incompatibilidades', 'El cargo de Juez o Magistrado es incompatible:',
  'Con todo tipo de asesoramiento jurídico, sea o no retribuido.', ['Con el asesoramiento jurídico retribuido, pero no con el gratuito.', 'Con el asesoramiento jurídico en materias ajenas a su jurisdicción.', 'Con todo tipo de asesoramiento jurídico, salvo que lo autorice el Consejo General del Poder Judicial.'],
  '7.º Con todo tipo de asesoramiento jurídico, sea o no retribuido.');
q('art. 389.8.º', 'Incompatibilidades', 'El cargo de Juez o Magistrado es incompatible:',
  'Con el ejercicio de toda actividad mercantil, por sí o por otro.', ['Con el ejercicio de la actividad mercantil por sí, pero no por otro.', 'Con el ejercicio de la actividad mercantil habitual, no con la ocasional.', 'Con la titularidad de acciones de sociedades mercantiles, por sí o por otro.'],
  '8.º Con el ejercicio de toda actividad mercantil, por sí o por otro.');
q('art. 392.1.b)', 'Incompatibilidad por parentesco o relaciones', 'Son incompatibles los Magistrados de cualquier Sala de Justicia, constituya o no sección orgánica, a la que se halle atribuido el conocimiento de los recursos respecto de las resoluciones de un órgano jurisdiccional, con los Jueces o Magistrados de dicho órgano. Se exceptúan de esta incompatibilidad:',
  'Las Salas y Secciones del Tribunal Supremo.', ['Las Salas y Secciones de la Audiencia Nacional.', 'Las Salas de lo Civil y Penal de los Tribunales Superiores de Justicia.', 'Las Salas y Secciones del Tribunal Supremo y de la Audiencia Nacional.'],
  'Se exceptúan de esta incompatibilidad las Salas y Secciones del Tribunal Supremo.');
q('art. 398.1', 'Inmunidad judicial', 'Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos:',
  'Por orden de Juez competente o en caso de flagrante delito.', ['Por orden del Consejo General del Poder Judicial o en caso de flagrante delito.', 'Por orden de Juez competente, sin excepción, aun en caso de flagrante delito.', 'Por orden del Ministerio Fiscal o en caso de flagrante delito.'],
  '1. Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito. En este último caso se tomarán las medidas de aseguramiento indispensables y se entregará inmediatamente el detenido al Juez de Instrucción más próximo.');
q('art. 410', 'Responsabilidad penal', 'Si se formula querella contra el juez o magistrado que deba resolver en un proceso, con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá recabar los antecedentes que considere oportunos a fin de determinar:',
  'Su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación.', ['La procedencia de la suspensión cautelar del juez y la gravedad de la infracción disciplinaria.', 'Su propia competencia, así como la existencia de responsabilidad civil subsidiaria del Estado.', 'La relevancia penal de los hechos y la competencia del Consejo General del Poder Judicial.'],
  'con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá recabar los antecedentes que considere oportunos a fin de determinar su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación.', true);
q('art. 543.2', 'Procuradores', 'Por delegación del juez, jueza o tribunal, los procuradores podrán realizar las actuaciones materiales propias del proceso de ejecución, que en todo caso excluirán:',
  'Las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia y las de desahucio por impago de rentas en viviendas habituales.', ['Las ejecuciones de sentencias dictadas en procesos de reclamación de cantidad inferior a seis mil euros.', 'Las ejecuciones hipotecarias de cualquier vivienda y las derivadas de procesos penales.', 'Los lanzamientos de ocupantes de finca anteriores a la subasta y los desahucios por precario.'],
  'Por delegación del juez, jueza o tribunal, podrán también realizar las actuaciones materiales propias del proceso de ejecución en los términos establecidos legalmente que, en todo caso, excluirán las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia, las de desahucio por impago de rentas o cantidades debidas en viviendas habituales');
q('art. 546.2', 'Abogados, Procuradores y Graduados Sociales', 'Los Abogados, Procuradores y Graduados Sociales están sujetos en el ejercicio de su profesión a responsabilidad:',
  'Civil, penal y disciplinaria, según proceda.', ['Civil y disciplinaria, pero no penal.', 'Civil y penal, quedando la disciplinaria reservada a los Colegios.', 'Penal y disciplinaria, según proceda.'],
  '2. Los Abogados, Procuradores y Graduados Sociales están sujetos en el ejercicio de su profesión a responsabilidad civil, penal y disciplinaria, según proceda.');
q('art. 550.2', 'Policía Judicial', 'Los funcionarios de Policía Judicial a quienes se hubiera encomendado una actuación o investigación concreta no podrán ser removidos o apartados hasta que finalice la misma o, en todo caso, la fase del procedimiento judicial que la originó, si no es:',
  'Por decisión o con la autorización del juez o fiscal competente.', ['Por decisión de su superior jerárquico, previa comunicación al juez o fiscal.', 'Por acuerdo del Consejo General del Poder Judicial.', 'Por decisión del Ministro del Interior o con autorización del Delegado del Gobierno.'],
  'si no es por decisión o con la autorización del juez o fiscal competente.');

q('art. 86.5', 'Secciones de Familia, Infancia y Capacidad', 'La jurisdicción de las Secciones de Familia, Infancia y Capacidad será exclusiva y excluyente, entre otras, en las materias que:', 'Versen exclusivamente sobre guarda y custodia de hijos o hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores.', ['Versen sobre la sucesión hereditaria y las donaciones entre parientes dentro del cuarto grado.', 'Versen sobre alimentos reclamados por los padres contra los hijos mayores de edad.', 'Versen sobre la responsabilidad penal de los menores de dieciocho años.'], '5. Las Secciones de Familia, Infancia y Capacidad conocerán de cuantas cuestiones se susciten en materia de familia en los términos previstos en las leyes. En todo caso, la jurisdicción de estas Secciones será exclusiva y excluyente en las siguientes materias:');
module.exports = R;